      "   lo <- 0 ; hi <- r",
      "   while lo <= hi",
      "      i <- floor((lo+hi)/2)",
      "      j <- r",
      "      if A[i+1] < B[j]   then lo <- i+1",
      "      else if B[j+1] < A[i] then hi <- i-1",
      "      else return max(A[i], B[j])"
